151	#define ROL(x,y) (((U32_T)(x) << ((y)&31)) | ((U32_T)(x) >> ((y)&31)))
152	#define ROR(x,y) (((U32_T)(x) >> ((y)&31)) | ((U32_T)(x) << ((y)&31)))
153	
154	#define _P 0xb7e15163UL
155	#define _Q 0x9e3779b9UL
156	
157	static
158	void
159	rc5_crypt( U32_T *a, U32_T *b, const U32_T *C, unsigned int rounds)
160	{
161	  U32_T A,B;
162	  unsigned int k;
163	
164	  A = *a; B = *b;
165	  A = A + C[0];
166	  B = B + C[1];
167	  for (k=2; k<2*rounds+2; ) {
168	    A = A^B;
169	    A = ROL(A,B);
170	    A = A+C[k];
171	
172	    B = A^B;
173	    B = ROL(B,A);
174	    B = B+C[k+1];
175	    k = k+2;
176	  }
177	  *a = A;
178	  *b = B;
179	}
