181	
182	static
183	void
184	rc5_decrypt( U32_T *a, U32_T *b, const U32_T *C, unsigned int rounds )
185	{
186	  U32_T A,B;
187	  unsigned int k;
188	
189	  A = *a;
190	  B = *b;
191	  for (k=2*rounds; k!=0; ) {
192	    B = B - C[k+1];
193	    B = ROR(B,A);
194	    B = B^A;
195	
196	    A = A - C[k];
197	    A = ROR(A,B);
198	    A = B^A;
199	    k = k-2;
200	  }
201	  B = B - C[1];
202	  *b = B;
203	  A = A - C[0];
204	  *a = A;
205	}
