208	static void
209	rc5_schedule( U32_T *S, U32_T LA, U32_T LB, unsigned int r)
210	{
211	  unsigned int i, k, NKEYS = 2*(r+1);
212	  U32_T A=0;
213	
214	  A = S[0]  = ROL( _P,	3);
215	  	LA  = ROL( LA	+A,	A );
216	  A = S[1]  = ROL( _P+_Q +A+LA,	3);
217	  	LB  = ROL( LB	+A+LA,	A+LA );
218	
219	  for ( S[2]=_P+2*_Q, i=3; i<NKEYS; i++) S[i] = S[i-1]+_Q;
220	
221	  k = 0;
222	  i = 2;
223	  do {
224	    do
225	    {
226	      A = S[i]  = ROL( S[i]  +A+LB, 3);
227	            LA  = ROL( LA    +A+LB, A+LB );
228	      A = S[i+1]= ROL( S[i+1]+A+LA, 3);
229		    LB  = ROL( LB    +A+LA, A+LA );
230	      i+=2;
231	    } while (i<NKEYS);
232	    k++;
233	    i = 0;
234	  } while (k < 3);
235	}

