/* probe.c - instrumented driver: reuses pMARS internals to report
 * per-round starting positions and dump the core after the battle.
 * Link against the original pMARS objects (except pmars.o). */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include "global.h"
#include "sim.h"

void simulator1(void);
void init(void);
void pspace_init(void);
int  parse_param(int argc, char **argv);
S32_T checksum_warriors(void);
ADDR_T rng(ADDR_T x);

static void dump_core(const char *fname)
{
  FILE *f = fopen(fname, "w");
  ADDR_T p0 = warrior[0].position;
  ADDR_T p1 = warrior[1].position;
  if (!f) return;
  fprintf(f, "warrior0 at %d len %d\nwarrior1 at %d len %d\n",
          p0, warrior[0].instLen, p1, warrior[1].instLen);
  for (ADDR_T i = 0; i < coreSize; i++) {
    unsigned long rel0 = (i - p0 + coreSize) % coreSize;
    unsigned long rel1 = (i - p1 + coreSize) % coreSize;
    if (rel0 < warrior[0].instLen || rel1 < warrior[1].instLen ||
        memory[i].opcode || memory[i].A_value || memory[i].B_value)
      fprintf(f, "%4d [%5ld] %c", i, (long)rel0,
              "DFJMSADP"[memory[i].opcode / 8]);
    else
      continue;
    fprintf(f, "  a=%d b=%d\n", memory[i].A_value, memory[i].B_value);
  }
  fclose(f);
}

int
main(argc, argv)
int     argc;
char  **argv;
{
  int   i;
  char *env;

  if ((errorcode = parse_param(argc, argv)) == 0) {
    init();
    for (i = 0; (i < warriors) && (errorcode == SUCCESS); i++)
      if (assemble(warrior[i].fileName, i))
        errorcode = 1;
    if (errorcode == SUCCESS) {
      pspace_init();
      if ((env = getenv("PROBE_SEQ"))) {
        /* replay the exact position sequence of the r rounds */
        ADDR_T positions = coreSize + 1 - (separation << 1);
        S32_T  seed = rng(checksum_warriors());
        int    n = atoi(env);
        if (n <= 0) n = rounds;
        for (i = 0; i < n; i++) {
          printf("round %3d  opp_pos=%d\n", i + 1,
                 (int)(separation + seed % positions));
          seed = rng(seed);
        }
      } else {
        simulator1();
        printf("PROBE: pos0=%d len0=%d | pos1=%d len1=%d | w0: %d-%d-%d | w1: %d-%d-%d\n",
               warrior[0].position, warrior[0].instLen,
               warrior[1].position, warrior[1].instLen,
               warrior[0].score[0], warrior[0].score[1], warrior[0].score[2],
               warrior[1].score[0], warrior[1].score[1], warrior[1].score[2]);
        if (getenv("PROBE_DUMP"))
          dump_core("coredump.txt");
      }
    }
  }
  return 0;
}

